window.RP_SESSION={"id":"S-d374e26a3646","messages":[{"id":"RP-III-0056796","time":"2026-03-28T17:27:00+09:00","room":"RP III","name":"니콜라스 아르메리아","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"니콜라스는 오늘도 길드 구석에서 책장을 정리하고 있었습니다. 낡은 책장에 꽂힌 책 몇 권을 와락 빼내자 얼굴로 먼지가 날아듭니다. 안 그래도 민감하던 눈은 한 층 더 붉어졌고, 그보다도 큰 문제는 폐에서부터 미친듯이 올라오는 기침일겁니다.","characters":["P-216ccc194078"]},{"id":"RP-III-0056797","time":"2026-03-28T17:27:00+09:00","room":"RP III","name":"니콜라스 아르메리아","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"콜록.\n콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록콜록","characters":["P-216ccc194078"]},{"id":"RP-III-0056798","time":"2026-03-28T17:28:00+09:00","room":"RP III","name":"캐너리 지엘리히","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 도와 드릴까요...? \"","characters":["P-ec8583137a09"]},{"id":"RP-III-0056799","time":"2026-03-28T17:30:00+09:00","room":"RP III","name":"니콜라스 아르메리아","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"삐걱거리는 소리라도 날 새라 까치발을 들고 있던 그가 도서관에서 이런 큰 소리를 내는 건 있을 수 없는 일일 겁니다. 더해서 캐너리의 목소리를 듣곤 누군가 있다는 걸 알자마자 자괴감이 몰려옵니다.\n\n\"됐, 어 필요 없어.\"\n\n그렇게 내뱉으며 굳은 얼굴을 한 채 먼지털이로 책장 사이를 털었습니다. 정확히는 때렸다고 해야 맞을지도 모르겠습니다.","characters":["P-216ccc194078"]}]};
